me:AddMsg(XT("[NAME]撬开锈死的锁扣，匣中封存的古修神念散逸而出，隐约指向几处上古修行者的踪迹……"));
local ok, err = pcall(function()
	local Evt = GameEventMgr or CS.XiaWorld.GameEventMgr.Instance;
	for i = 1, 3 do
		Evt:TriggerEvent(97);
	end
end);
if not ok then
	print("[JadeStartMod] 古修秘匣触发失败: " .. tostring(err));
end
story:RemoveBindItem();


me:AddMsg(XT("[NAME]解开红绳打开礼包，箱底一缕气运散作清风，飘向山门之外……"));
--参数说明：个数 / 品质等级（实际无效）(1-10) / 滞后时间(天) / 五维附加值 / 种族
me:AddJoiners(30, 9, 0, 9, 9, 9, 9, 9, "Human");
me:AddMsg(XT("不多时，山门外来了三十名凡人，说是流落至此，愿在山门求一处安身之所。"));
story:RemoveBindItem();


me:AddMsg(XT("[NAME]拆开礼包，一枚无名玉简落入掌心，玉简一触即碎，化作无数感悟涌入识海……"));
--第二个参数 true = 不走心情/悟性系数，原样加 80 亿
me:AddTreeExp(8000000000, true);
me:AddMsg(XT("良久，[NAME]睁开双眼，胸中已是豁然贯通。"));
story:RemoveBindItem();


me:AddMsg(XT("[NAME]解开礼包，里头是一叠发黄的卷宗，字迹杂乱，却处处指向同一段旧事……"));
local ok, err = pcall(function()
	local JH = CS.XiaWorld.JianghuMgr.Instance;
	for id = 1, 29 do
		JH:UnLockClue(id, false);
	end
	JH:UnLockClue(43, false);
end);
if ok then
	me:AddMsg(XT("卷宗阅罢，江湖秘闻中「神秘身影」「灭门之谜」「外传-上古信息」的线索尽数在握。"));
	me:AddMsg(XT("（外传说明）打开「江湖」界面的「秘闻」，进「外传：上古信息」，把「上古信息」这条线索选进「动机」栏，其余两栏随手挑几条已得的线索填上即可解开。"));
else
	print("[JadeStartMod] 线索解锁失败: " .. tostring(err));
	me:AddMsg(XT("可惜卷宗字迹含糊难辨，终究没能理出个头绪。"));
end
story:RemoveBindItem();
